const MVLC_ENT_EXAMPLES=[
{n:"2.22 Example 1 — Mr. Doe, St. Louis MO",story:"Entitlement code 04, Army, exempt. One prior loan, IL, $112,000 (07/01/1990), $36,000 entitlement charged, status Foreclosure/Deed in Lieu. Basic entitlement $0; total charged $36,000. Mr. Doe wants to buy in St. Louis where the conforming limit is $806,500. Can he still buy, and how much with no down payment?",cll:806500,used:36000,price:0,answer:"Yes. Max entitlement in the county = 25% × $806,500 = $201,625. Remaining = $201,625 − $36,000 = $165,625. Max loan with no down payment = $165,625 × 4 = $662,500. The foreclosure charge stays until VA's loss is repaid, but the bonus entitlement above $36,000 is untouched."},
{n:"2.23 Example 2 — PCS from WA to Jacksonville FL",story:"Entitlement code 10, Army, exempt (SC with monthly award). One active loan, WA, $1,275,000 (03/14/2022), $318,750 charged, keeping the home. Jacksonville's county limit is $806,500. Enough entitlement to buy?",cll:806500,used:318750,price:0,answer:"No remaining entitlement in Duval County: $201,625 max − $318,750 used is negative. The veteran can still use VA, but with $0 entitlement the lender's 25% coverage must come entirely from a down payment of 25% of the purchase price (or a smaller price). Options: sell/refinance the WA home to restore, or buy with 25% down, or use a non-VA program."},
{n:"2.25 Example 1 — Dallas TX, $575,000",story:"Existing VA loan ties up $109,638 of entitlement. Dallas County limit $806,500.",cll:806500,used:109638,price:575000,answer:"Max entitlement $201,625 → remaining $91,987 → max loan without DP $367,948 → difference $207,052 → required down payment 25% = $51,763."},
{n:"2.26 Example 2 — Arlington VA, $900,000",story:"Two existing VA loans using $51,713 and $118,200. Alexandria County limit $1,209,750.",cll:1209750,used:169913,price:900000,answer:"Max entitlement $302,437.50 → remaining $132,524.50 → max loan without DP $530,098 → difference $369,902 → required down payment 25% = $92,475.50."}];
function mvlcEntitlement(a){const cll=+a.cll||0,used=+a.used||0,price=+a.price||0;const maxEnt=cll*0.25;const remaining=Math.max(0,maxEnt-used);const maxLoan=remaining*4;const diff=price?Math.max(0,price-maxLoan):0;const dp=price?(remaining>0?diff*0.25:price*0.25):0;return{maxEnt,remaining,rawRemaining:maxEnt-used,maxLoan,diff,dp,noEntitlement:remaining<=0,basicOnly:used<=0?36000*4:null}}
/* Joint loan math (2.39–2.42). Vet share s of the price; guaranty = 25% of the vet's portion of the loan; GNMA needs 25% of price covered by guaranty + down payment. The guide's 14.209143% matches when the veteran's funding fee is financed. */
function mvlcJoint(a){const P=+a.price||0;const s=Math.min(1,Math.max(0,(+a.vetShare||50)/100));const f=(+a.ff||0)/100;const fin=a.financeFF!==false;const g=0.25*s*(fin?1+f*s:1);let dpPct=0;if(s<1){dpPct=Math.max(0,(0.25-g)/(1-g))}const dp=P*dpPct;const base=P-dp;const ffAmt=f*s*base;const total=base+(fin?ffAmt:0);const vetPortion=s*total;const guaranty=0.25*vetPortion;const avgFee=P?ffAmt/base:0;return{dpPct,dp,base,ffAmt,total,vetPortion,guaranty,avgFee,investment:guaranty+dp,need:0.25*P}}
function mvlcVetVet(a){const P=+a.price||0;const parts=(a.vets||[]).map(v=>{const share=P*((+v.share||50)/100);const fee=(v.exempt?0:(+v.rate||2.15)/100);return{share,entNeeded:share*0.25,fee,feeAmt:share*fee,enough:(+v.avail||0)>=share*0.25}});const totalFee=parts.reduce((t,p)=>t+p.feeAmt,0);return{parts,totalFee,avgFee:P?totalFee/P:0,dpNeeded:parts.some(p=>!p.enough)}}
/* 6.4 seasoning, 4.10 ETS, 4.7 LES age */
function mvlcSeasoning(firstDue,paymentsMade){if(!firstDue)return null;const d=new Date(firstDue);const d210=new Date(d);d210.setDate(d210.getDate()+210);const sixth=new Date(d);sixth.setMonth(sixth.getMonth()+5);const earliest=new Date(Math.max(d210,sixth));return{d210,sixth,earliest,ok:(+paymentsMade||0)>=6&&new Date()>=earliest}}
function mvlcEts(ets,close){if(!ets||!close)return null;const e=new Date(ets),c=new Date(close);const months=(e-c)/(1000*60*60*24*30.44);return{months,ok:months>=12,needs:months<12?"LOE of intent to re-enlist + Statement of Service on eligibility/ability to re-enlist (or enlistment papers/new orders if already re-enlisted); if separating within 12 months and not re-enlisting, active-duty income CANNOT be used":"ETS is 12+ months past close — income usable as stable"}}
function mvlcLesAge(les,ref,newConstruction){if(!les||!ref)return null;const days=Math.round((new Date(ref)-new Date(les))/86400000);const limit=newConstruction?180:120;return{days,limit,ok:days>=0&&days<=limit}}
/* The guide, chapter by chapter. sec: [n, heading, paragraphs[], bullets[], tip] — tip may be "". */
const MVLC_CHAPTERS=[
{id:"c1",n:1,title:"The VA Loan",sub:"History, statistics, misconceptions, and resources",obj:["Understand the VA home loan program history","National VA loan statistics","Common myths and misconceptions","VA loan resources"],sec:[
 ["1.1","VA Home Loan Program history",["The Home Loan Guaranty program was originally conceived in 1944 to help veterans buy homes when returning from World War II.","It was one of the major innovations and most important part of the original Servicemen's Readjustment Act of 1944 (the GI Bill).","The Home Loan Guaranty was an alternative device to a cash bonus — vastly less expensive to the government and better suited to the needs of veterans."],[],""],
 ["1.2","2024 national statistics snapshot",["Source: Department of Veterans Affairs. Purchase loans were 62% of volume; IRRRLs 20%; other refinances 18%. The table is reproduced in the Stats panel of this course."],[],"Use these when a listing agent says 'VA buyers never close' — 40,408 guaranteed loans, $15.58B, in the snapshot year."],
 ["1.3","2023 national purchase statistics",["Source: Department of Veterans Affairs and the VA 2023 Lender's Scorecard. Median DTI 43.8%, median score 715, median loan $372,886, median income $98,880, median assets $19,819, 18.8 days average from VA case number to guaranty. 60% of VA clients are previous homeowners; 25% choose to make a down payment."],[],"Median DTI above 41% proves the residual-income path is the normal path, not the exception."],
 ["1.4","Fact or fiction",["Ten myths the guide asks you to rebut — the Myths panel of this course gives each with the fact and the section that proves it."],[],""],
 ["1.5","VA loan resources",["Reaching VA: (877) 827-3702, Monday–Friday 8:00–6:00 pm Eastern; the VA Service Portal, Lenders Handbook (Pamphlet 26-7), circulars, the gov.delivery sign-up for new circulars, and Lender Statistics. The Resources panel lists each link as printed in the guide."],[],""]]},
{id:"c2",n:2,title:"VA Loan Basics",sub:"Eligibility, COEs, entitlement, VA funding fee, occupancy, and joint loans",obj:["What is the VA loan guaranty","Eligible and ineligible VA loan purposes","Basic requirements for VA loan eligibility","The importance of the COE and how to read it","Entitlement — full vs partial, basic and bonus","Explaining the VA funding fee","VA required occupancy","The VA joint loan"],sec:[
 ["2.1","Meaning of a 'VA guaranteed' loan",[],["The Department of Veterans Affairs (VA) is not a bank.","VA does not loan the money, fund the loan, or service the loan.","VA 'stands behind' the loan by guaranteeing a portion of it.","If the borrower can't make payments, the lender can go to VA to cover losses it might incur.","The guarantee replaces the protection a lender normally gets from a down payment or mortgage insurance, giving veterans favorable terms.","Most VA home loans are handled entirely by private lenders; VA rarely gets involved in loan approval."],""],
 ["2.2","Features of a VA purchase loan",[],["Must be for the veteran's own personal occupancy.","Max guaranty is up to 25% of the loan amount for veterans with full entitlement.","Up to the one-unit FHFA max county loan limit (CLL) for partial entitlement.","No down payment may be required — up to 100% financing.","Ability to finance the VA funding fee.","Only fixed or ARM, fully amortizing — no interest-only options."],""],
 ["2.3","Basic requirements for a VA loan approval",[],["Eligible veteran with available entitlement and a valid Certificate of Eligibility (COE).","The loan must be for an eligible purpose.","The veteran must occupy the property as a primary residence within a reasonable period after closing.","The veteran must be a satisfactory credit risk.","Income must be stable and sufficient to meet the mortgage payment, the cost of owning a home and other obligations — and still have enough left to support the family (residual income)."],""],
 ["2.4","VA eligible loan purposes",[],["Purchase a 1–4 unit primary residence.","Refinance an existing VA loan for a lower interest rate (IRRRL).","Refinance an existing mortgage or other lien of record on a residence owned and occupied by the veteran.","Simultaneously purchase or refinance to repair, alter, or improve a residence owned and occupied by the veteran.","Improve an owned and occupied residence with energy-efficiency updates — can be made with any VA purchase or refinance.","Purchase a one-family unit in a VA-approved condominium development."],""],
 ["2.5","VA ineligible loan purposes",[],["Purchase of unimproved land to improve later (land not in conjunction with a construction loan).","Purchase or construction of a dwelling for investment purposes.","Purchase or construction of combined residential and business property — unless primarily residential, not more than one business unit, and the nonresidential area does not detract from the residential nature."],""],
 ["2.6","Additional VA guaranty programs",[],["Interest Rate Reduction Refinance Loan (IRRRL)","VA cash-out refinance","VA new construction and VA renovation loans","Special housing grants (SAH/SHA)","Energy efficient loans","Native American Direct Loan (NADL)","State-funded VA home loans (e.g., CalVet)","VA loan assumption"],""],
 ["2.7","Eligibility — active duty (90-day / six-month rule)",["A service member is eligible while serving on active duty in the Army, Navy, Marine Corps, Air Force, Coast Guard, or Space Force after:"],["90 days or more, any part of which occurred during wartime, or","181 continuous days or more (peacetime)."],""],
 ["2.8","Eligibility — veterans (two-year rule if not on active duty)",["A greater length of service is required for veterans no longer on active duty who enlisted (and service began) after September 7, 1980, or entered service as an officer after October 16, 1981 — generally 24 continuous months, or the full period called/ordered to active duty (at least 90 days wartime / 181 peacetime).","A veteran could have been eligible under the 90-day rule while serving but, by not completing 24 months, is no longer eligible after separation. *This rule is due to active legislation."],[],"Read the DD-214 'net active service' block and the narrative reason for separation before promising eligibility."],
 ["2.9","Eligibility — Reserves and National Guard",["Members not otherwise eligible become eligible on completing six years of service in the Reserves or Guard (unless released earlier for a service-connected disability). The applicant must have an honorable discharge (general or under-honorable-conditions does not qualify) unless in an inactive status awaiting final discharge or still serving.","Point statements must show 6 years with 15 membership points per anniversary year plus at least 1 inactive- or active-duty training point each year (16 total per year) and an honorable discharge."],[],"Run the reservist points tester in the VA Mastery course for a quick check."],
 ["2.10","Surviving spouses",[],["The unmarried surviving spouse of a veteran who died as a result of service or service-connected causes.","The surviving spouse of a veteran who died on active duty or from service-connected causes, who remarries on or after age 57 and on or after December 16, 2003.","The spouse of an active-duty member listed MIA or POW for at least 90 days — limited to one-time use."],""],
 ["2.11","Other eligible individuals & additional eligibility notes",["Congress has periodically granted veteran status to groups outside the formal branches — certain Public Health Service members, service-academy cadets, certain merchant seamen, etc.","One day of service is sufficient for an individual discharged or released (regular active duty or Reserve/Guard) due to a service-connected disability.","Eligibility does not expire — something veterans themselves don't always understand."],[],""],
 ["2.12","The Certificate of Eligibility (COE)",["Obtaining this document as early as possible in the transaction is critical — the guide says 'we cannot stress this enough.' VA provides the COE; it tells the lender the borrower is eligible.","The lender can request it through VA's WebLGY portal; the veteran can request through eBenefits/VA.gov. When an automated COE is not available, VA Form 26-1880 (Request for a Certificate of Eligibility) is needed with the appropriate proof of service."],[],"Form 26-1880 sections: I identifying info (name as on COE, other names, discharge for disability?); II military service (active duty now? Purple Heart? pre-discharge claim pending? branch/dates for active and Reserve/Guard periods); III previous VA loans (how you'll use the COE; prior loans; still own?; restoration type — cash-out, IRRRL, one-time)."],
 ["2.13","Proof of service requirements",["Proof of service must be provided for discharged veterans (regular military), veterans still on active duty, discharged Reserve/Guard members, and current Reserve/Guard members. The Documents panel maps each status to its form (DD-214, Statement of Service, NGB 22/23, reserve point statements)."],[],"Only the DD-214 Member-4 copy shows character of service — the Member-1 copy omits it and will be kicked back."],
 ["2.14","Obtaining proof of service",[],["VA.gov — download VA letters/records","National Personnel Records Center online (eVetRecs) — archives.gov","Complete the SF-180, Request Pertaining to Military Records, and submit to the address on the form"],""],
 ["2.15","COE entitlement codes",["Codes 01–11 identify the era/status and tell you the funding-fee class — see the Codes panel. 05 = prior use (subsequent-use fee); 06/07 = surviving spouse / POW-MIA spouse (no fee); 10 = Persian Gulf including Guard/Reserve with qualifying Title 10 call-up; 11 = Selected Reserve without a Title 10 call-up."],[],""],
 ["2.16","Prior loans charged to entitlement",["The COE table lists each prior VA loan: number, state, amount, date, entitlement charged, status — Active, Paid in Full/No Restoration, Compromise, Foreclosure/Deed in Lieu. The Statuses panel explains what each does to available entitlement. Example: a foreclosure letter from the Cleveland RLC states the loss amount and LIN and that entitlement cannot be restored until the loss is repaid — but the remaining entitlement can still be used."],[],""],
 ["2.17","COE conditions",["Conditions give specifics on the use of the COE: subsequent use, funding fee status, Purple Heart, active-duty service member (certification of continuous active duty as of note date; pre-discharge claim handling with 26-8937), Reserve or National Guard member, surviving spouse, one-time restoration, foreclosure/deed-in-lieu/compromise, and the funding-fee refund notice (rating effective before closing → contact servicer or RLC at 877-827-3702)."],[],""],
 ["2.18","Maximum guaranty on a VA loan",[],["VA does not set a cap on how much a veteran can borrow.","As of January 1, 2020, VA removed the guaranty cap for veterans with full entitlement.","Caps/loan limits apply only to the maximum VA will guaranty when the veteran has partial entitlement — VA follows FHFA one-unit limits by county (verify at fhfa.gov / va.gov loan limits)."],""],
 ["2.19","Full vs partial entitlement",["Full entitlement: unlimited entitlement available. Partial entitlement: based on conforming loan limits (FHFA one-unit table); veterans can receive a loan up to 4 times their available entitlement without a down payment."],[],""],
 ["2.20","Basic entitlement",["The basic entitlement available to each eligible veteran is $36,000 — the amount VA will guarantee. With a 25% guaranty, $36,000 × 4 = $144,000 max loan with no down payment using only basic entitlement."],[],""],
 ["2.21","Bonus entitlement",["The Veterans Benefits Improvement Act of 2004 increased the maximum guaranty for loans over $144,000 by indexing it to 25% of the conventional conforming loan limit — adjusting automatically each year with the limit."],[],""],
 ["2.22–2.23","Calculating remaining entitlement — Examples 1 and 2",["Mr. Doe (St. Louis) and the WA→Jacksonville PCS case — both worked in the Entitlement calculator with the guide's answer key."],[],""],
 ["2.24","Calculating down payment requirements",["A down payment is needed when the veteran wants a home that costs more than remaining entitlement will cover: VA requires 25% of the difference between what VA will guaranty (remaining entitlement × 4) and the purchase price."],[],""],
 ["2.25–2.26","Down payment examples (answer key p.81)",["Dallas $575,000 with $109,638 used at an $806,500 limit → $51,763 down. Arlington $900,000 with $169,913 used at a $1,209,750 limit → $92,475.50 down. Reproduce them in the calculator."],[],""],
 ["2.27","VA loan restoration",["A veteran may have used eligibility before; it doesn't prevent a new VA loan but the prior loan may need to be cleared off the COE. Two types: Basic Restoration (loan paid in full and property disposed of) and Special/One-time Restoration (paid in full, property kept)."],[],"Rapid Restoration: if the veteran is selling the existing VA-financed home and buying the next shortly after, request a 'rapid restore' through the lender — the RLC restores eligibility on a short timeline with the payoff/closing statement."],
 ["2.28","The VA funding fee",["Required by law to sustain the guaranty program; VA collects a fee on each transaction. The VA loan is not taxpayer funded."],["Can be financed into the loan","Seller can pay it as part of the 4% concessions","Can be reduced with a down payment","Waived for those with exemptions"],""],
 ["2.29","The VA funding table",["Regular and Reserve/Guard now share the same schedule: 2.15% first use / 3.3% subsequent with no down; 1.50% with 5%+ down; 1.25% with 10%+ down; IRRRL 0.5%; assumption 0.5%; disabled receiving compensation: none."],[],""],
 ["2.30","Funding fee exemptions",["Purple Heart on active duty; veterans receiving compensation for service-connected disabilities; those who would receive compensation but for retirement pay; those rated eligible from a pre-discharge exam or memorandum rating."],[],""],
 ["2.31","Verifying exempt status",["The COE indicates exempt status. If it doesn't and the veteran believes they should be exempt: formal documentation evidencing the disability rating is provided to VA for research and reissuance of an updated COE."],[],""],
 ["2.32","Active duty with pending pre-discharge claims",["VA requires lenders to ask active-duty members if a pre-discharge claim is pending. If so, VA Form 26-8937 (Verification of VA Benefits) is completed and submitted with the original COE; VA reviews and issues an updated COE showing Non-Exempt, Exempt, or Non-Exempt – In Development.","NOTE: if status is Non-Exempt or In Development and closing occurs before discharge, the exemption does not apply and the member will not be entitled to a refund."],[],"Form 26-8937 is completed only if the applicant is receiving disability pay, has applied for it, would receive it but for retired pay, filed a pre-discharge claim, or is a surviving spouse receiving DIC. The RLC certifies exempt/not exempt and any VA benefit-related indebtedness."],
 ["2.33","VA loan occupancy requirement",["The law requires the veteran to certify intent to personally occupy the property as their home: either live in it now, or intend on completion of the loan to move in within a reasonable time."],[],""],
 ["2.34","Reasonable time occupancy",["Typically within 60 days after closing. More than 60 days may be reasonable if the veteran certifies a specific date and a particular future event makes occupancy possible on that date. Occupancy beyond 12 months after closing generally will not be considered reasonable."],[],""],
 ["2.35","Occupancy by spouse or dependent child",["Occupancy (or intent) by the spouse or dependent child satisfies the requirement for a veteran on active duty who cannot personally occupy within a reasonable time. For a dependent child, the veteran's attorney-in-fact or the child's legal guardian certifies and signs VA Form 26-1820 (Report and Certification of Loan Disbursement)."],[],""],
 ["2.36","Occupancy for deployed members",["Single or married servicemembers deployed from their permanent duty station are in temporary-duty status and meet occupancy — regardless of whether a spouse will occupy before the veteran returns."],[],""],
 ["2.37","Other types of occupancy",[],["Occupancy after retirement (retiring within 12 months — documented)","Delayed occupancy for repairs or improvements","Intermittent occupancy"],""],
 ["2.38","Joint loans defined",["A 'joint loan' is one where the veteran and any person other than the spouse are liable for the loan and/or own the property: (1) veteran + one or more non-veterans (not spouse); (2) veteran + veterans not using entitlement; (3) veteran + other veterans all using entitlement. Veteran and spouse are 'one entity' — not a joint loan if the spouse is not a veteran or is a veteran not using entitlement."],[],""],
 ["2.39","Veteran and veteran (both using entitlement)",[],["Both must occupy since both use entitlement.","VA splits entitlement equally if equal amounts are available; unequal splits allowed when one lacks enough and the other covers the remainder — acknowledgement by both required.","Down payment: none if combined entitlement covers the loan.","Funding fee: each veteran's fee is calculated individually on their equal portion of the loan regardless of the entitlement split.","Does NOT require prior approval from VA."],""],
 ["2.40","Case study: veteran & veteran",["Two veterans (not spouses) buy a $700,000 home. Vet 1's half is $350,000, covered by $87,500 of available entitlement (they keep a current VA loan using $50,000 and still have enough) — subsequent user, not exempt. Vet 2's half is $350,000, covered by $87,500 — first-time user and exempt. Both occupy; no down payment; the funding fee on the $700,000 loan averages 1.65% (Vet 1 3.3% on $350,000, Vet 2 0%)."],[],""],
 ["2.41","Veteran and non-veteran",[],["Veteran must occupy; non-veteran does not.","VA guarantees the veteran's portion only.","Down payment required on the non-veteran's portion (from either party's assets) — total investment must meet GNMA's 25% of purchase price between entitlement and DP, about 14.3%.","Funding fee calculated on the veteran's portion only; the non-veteran pays none.","The veteran must qualify for their portion of the housing payment on their own income/debts.","VA REQUIRES prior approval before the loan can close."],""],
 ["2.42","Case study: veteran / non-veteran",["Veteran buys a $700,000 home with a non-veteran friend in Prince George County, VA. Veteran's half $350,000 with ample entitlement; first-time user, not exempt. Non-veteran's half $350,000 not covered. Down payment to reach the full 25% GNMA investment — 14.209143% of price = $99,464*. Funding fee averages .625% (Vet 1.25%* on $350,000 with the down payment, non-vet 0%). *Figures match when the veteran's fee is financed — see the Joint calculator."],[],""]]},
{id:"c3",n:3,title:"VA Loan Fees",sub:"Closing costs and seller concessions",obj:["Understand the VA allowable fees/closing costs","Properly explain the VA non-allowed fees","Know the difference between VA seller concessions and standard non-recurring closing costs"],sec:[
 ["3.1","Closing fees",["VA's goal is to protect veterans on closing costs, so VA defines fees that can and cannot be charged to the veteran (38 CFR 36.4312). If fees the veteran cannot be charged are not paid by the lender, agent, or seller, the loan will not fund and the transaction will not close."],[],""],
 ["3.2","Allowable fees / closing costs",["Per the Lender's Handbook (Chapter 8), a VA buyer can pay a maximum of: reasonable and customary amounts for the itemized fees VA designates allowable, plus a 1% flat charge by the lender (or itemized origination charges up to 1%), plus reasonable discount points."],[],""],
 ["3.3","Reasonable and customary itemized fees",["Customary fees the veteran may pay — see the Fees panel (appraisal/compliance inspections, recording, credit report, prepaids, hazard insurance, flood cert, survey, title exam/insurance, special mailing for refinances, VA funding fee, MERS fee, other fees authorized by VA, brokerage fees under the temporary variance)."],[],""],
 ["3.4","Lender's 1% flat charge (origination fee)",["The lender may charge a 1% origination fee or itemize the listed fees up to a total of 1% — lender's appraisals/inspections (not construction), closing/settlement/escrow/notary, doc prep, loan papers/conveyance/attorney (non-title), photographs, lock/commitment fees, postage/overhead, amortization schedules/pass books/membership fees."],[],""],
 ["3.4b","VA non-allowable fees — never allowed",[],["Attorney's fee (other than title work)","Pre-payment penalties","HUD/FHA inspection fee for builders"],""],
 ["3.5","1% rule and noteworthy points",[],["If no (or less than 1%) origination fee is charged, other origination charges can be itemized up to 1%.","New construction, alteration, improvement or repair loans allow an additional flat charge.","The seller, lender, or any other party (including agents) may pay fees and charges, including discount points, on behalf of the borrower — VA limits charges 'made against or paid by' the borrower, not what others pay, unless they fall into seller-concession rules.","Overpar/premium pricing IS NOT a lender credit — it is the veteran's own money and cannot be used to cover non-allowables."],""],
 ["3.6","Standard (non-recurring) closing costs",["Standard non-recurring closing costs ARE NOT seller concessions. The seller, lender, or any other party may pay standard fees and charges including normal discount points (typically up to two) on behalf of the borrower."],[],""],
 ["3.7","VA seller concessions",["A seller concession is anything of value added by the seller or builder for which the buyer pays nothing additional and which the seller is not customarily expected or required to pay or provide. VA allows concessions as long as they are not excessive — capped at 4%."],[],""],
 ["3.8","Closing fees and concessions",["VA allows other parties to pay ALL standard non-recurring closing costs PLUS 4% in concessions. Concessions include the buyer's funding fee, prepayment of taxes/insurance, gifts (TV, microwave), extra points for permanent buydowns (over 2 points), escrowed funds for temporary buydowns, and payoff of the buyer's credit balances or judgments."],[],"Do NOT include normal discount points and payment of the buyer's standard non-recurring closing costs in total concessions when testing the 4% limit."]]},
{id:"c4",n:4,title:"Qualifying",sub:"Underwriting, income, assets, debts, credit, and residual income",obj:["POAs and Alive & Well statements","Understand the VA loan underwriting guidelines","Explain the purpose of lender overlays","Active-duty income and the LES","Civilian income requirements","Asset and reserve requirements","Understand the debts, obligations and credit guidelines","Understand how credit affects the VA loan approval process","Residual income"],sec:[
 ["4.1","Power of Attorney (POA)",["VA allows an attorney-in-fact to execute documents, enabling active-duty members overseas and others who cannot be present to close. General POA — allowed if the veteran signed both the sales contract and the 1003. Specific POA — needed when the veteran did not sign both; it must include specific elements: entitlement, purpose, property identification, price and terms, and occupancy."],[],""],
 ["4.1b","Alive & Well (not MIA)",["The lender must always verify the veteran is alive at closing and, if an active-duty service member, not missing in action. VA may deny the guaranty if the lender failed to verify and the veteran was deceased or MIA when the loan closed."],[],""],
 ["4.2","Underwriting income objectives",["Identify and verify income available to meet the mortgage payment, other shelter expenses, debts and obligations, and family living expenses. Evaluate whether verified income is stable and reliable, anticipated to continue for the foreseeable future, and sufficient in amount."],[],""],
 ["4.3","VA lender responsibility",[],["Developing all credit information","Properly obtaining all required verifications and the credit report","Ensuring the accuracy of all information on which the loan decision is based","Complying with the law/regulations governing VA underwriting and VA policies, procedures and guidelines","Certifying compliance with all of the above"],""],
 ["4.4","Lender overlays",["An overlay is an additional rule a lender applies on top of a program's guidelines. Overlays vary from lender to lender, which causes confusion — one lender may have an overlay on an issue the next lender does not."],[],"A 'VA denial' is usually an overlay denial. Shop the file to a lender without that overlay before telling the veteran no."],
 ["4.5","General income guidelines",["Stable, reliable, and likely to continue. The most recent two years of income must be validated, or as determined by AUS with a minimum of one year verification required."],[],""],
 ["4.6","Active-duty pay — rank vs grade",["'Rank' is the member's title (named differently by service) and denotes authority. 'Grade' is the administrative pay classification; pay grades are the same across branches (E-1…E-9, W-1…W-5, O-1…O-10). The Ranks panel reproduces the insignia chart."],[],""],
 ["4.7","Active-duty income",[],["A military Leave and Earnings Statement (LES) is required instead of a VOE and must furnish the same information.","Loans closed automatically: LES dated within 120 days of the note date (180 days for new construction).","Prior-approval loans: LES within 120 days of the date VA receives the application (180 days new construction)."],""],
 ["4.9","The Leave and Earnings Statement",["Header blocks: name, SSN, GRADE (E3), PAY DATE, YRS SVC, ETS, BRANCH, ADSN/DSSN, PERIOD COVERED. Columns: ENTITLEMENTS (base pay, BAS, BAH…), DEDUCTIONS (taxes, SGLI, TSP, mid-month pay), ALLOTMENTS, SUMMARY (+TOT ENT, −TOT DED, −TOT ALMT, =NET AMT). Lower blocks: FED/FICA/STATE tax YTD, PAY DATA (BAQ type, VHA zip, dependents), TSP contributions."],[],""],
 ["4.10","LES important notes",[],["ETS = Expiration Term of Service (current obligated end date). If less than 12 months from the loan close date and the member plans to stay in, require an LOE of intent to re-enlist plus a Statement of Service on eligibility/ability to re-enlist; if already re-enlisted, use the enlistment papers and/or new orders.","If exiting the military within 12 months of close, active-duty income CANNOT be used for qualifying.","Officers have no ETS, only enlisted. Box 3 GRADE shows O for officer, E for enlisted; officers are expected to serve at least 20 years.","ENTITLEMENTS determine qualifying income — base pay, BAS and BAH can typically be used. Over 60 special/incentive pays and as many allowances exist; the pay must be guaranteed to continue — many are temporary and cannot be used.","ALLOTMENTS are monthly amounts (not per paycheck) the member auto-deducts — savings, charity, dental, or loan payments. Check them for undisclosed debt."],""],
 ["4.11","Reservists, Guard and active-duty applicants",[],["Continuation of military pay/allowances must be determined to count as income.","If duration cannot be determined, the pay/allowances will only be used to offset intermediate debts of 24 months or less.","It is up to the lender to separate allowances into taxable and tax-free categories."],""],
 ["4.12","Income of recently discharged veterans",["Obtain verification of employment income, retirement income, and military separation payments as applicable. These cases often require the underwriter to exercise flexibility and judgment on whether employment income will continue — some veterans have little or no employment experience other than their military occupation. Continuity of employment is essential when there is no or insufficient retirement income."],[],"Advocate with the MOS-to-civilian-job match: a 25U signal support specialist hired as a network tech is 'related experience' under §4.15."],
 ["4.13","Income from non-military employment",["The lender must verify a minimum of 2 years employment."],[],""],
 ["4.14","Income of applicant employed less than 12 months",["Generally not stable and reliable — but may be if the individual facts warrant. The lender needs to carefully consider the employer's evaluation of the probability of continued employment, if provided."],[],""],
 ["4.15","VA's general time requirement for income stability",["Standard 12 months (may include training/related experience); overtime, part-time, commission, second job 2 years and likely to continue; public assistance 3 years continuance; workers comp case by case; seasonal with documented history; GI Bill education allowance cannot be used. See the Income panel."],[],""],
 ["4.16","Alimony, child support, and maintenance",["Verify if the applicant wants it considered; payments must be likely to continue for three years. There must be a legal and binding agreement (no voluntary/handshake arrangements) plus a history of receipt."],[],""],
 ["4.17","Other income sources",["Temporary income (overtime, part-time, second jobs, bonuses) generally cannot be considered stable unless continued and verified for 2 years. Commission income typically after two years. 'Other' effective income includes pension/retirement, disability income, dividends, and interest/royalties."],[],""],
 ["4.18","Income of a spouse",["Treat the income of a spouse who will be contractually obligated the same as the veteran's. Under ECOA, lenders cannot ask about a spouse's income unless the spouse will be contractually liable, the applicant relies on the spouse's income, the applicant relies on alimony/child support from the spouse or former spouse, or the applicant resides in (or the security is in) a community property state — AZ, CA, ID, LA, NV, NM, TX, WA, WI."],[],""],
 ["4.19","Self-employment income",[],["2 years personal and business returns","Current financial statements in a generally recognized format: year-to-date profit and loss statement and current balance sheet"],""],
 ["4.20","Rental income",[],["Departing residence retained as a rental: rental offset only.","Multi-unit subject property using rental income: cash reserve of 6 months PITI, plus prior landlord/property-maintenance experience or an executed property-management contract.","Existing investment/rental property: property on the last two years' tax returns; 3 months PITI reserve for each rental.","Boarder income must appear on the last two years to be usable."],""],
 ["4.21","Assets",["The veteran must have sufficient verified cash/liquid assets to cover closing costs, prepaids and discount points not financed, any down payment, and the difference between sales price and loan amount if price exceeds VA's reasonable value — in that situation the down payment funds cannot come from a gift."],[],""],
 ["4.22","Reserves",["Reserves are only required by VA when rental income is used to qualify: subject multi-unit 6 months PITI; existing investment property 3 months PITI per property. The ability to accumulate liquid assets and availability of assets for unplanned expenses is considered in the overall credit analysis and can be a compensating factor on a marginal loan."],[],""],
 ["4.23","Gift funds",["Donor must have no affiliation with the builder, developer, agent, or any interested party. Required: executed gift letter and verification the funds were transferred to the veteran's account or documented as received by the closing agent. Acceptable documentation: evidence of the borrower's deposit, copy of the donor's check/electronic transfer to the closing agent, or the CD showing receipt."],[],""],
 ["4.25","Debts and obligations",["Significant debts and obligations must be verified and rated. Obtain a credit report for history and usage — the most recent 12–24 months is the most critical timeframe."],[],""],
 ["4.26","Minimum credit scores",["The VA loan is not FICO-score driven — there is no minimum FICO in the Lender's Handbook; underwriters are encouraged to use reasonable judgment and flexibility."],[],"Lender overlays (often 580–620) are the actual floor — shop them."],
 ["4.27","No credit score",["Lack of credit references is not necessarily a reason to deny. VA allows references from non-traditional sources — base the determination on the applicant's payment record on utilities, rent, auto insurance, or other expenses paid."],[],""],
 ["4.28","Child support and alimony obligations",["The payment amount on any legal and binding alimony and/or child support obligation must be verified."],[],""],
 ["4.29","Analysis of significant debts and obligations",["Deduct significant debts from total effective income. Significant = remaining term of 10 months or more (long-term), or accounts under 10 months whose payments are so large they severely impact the family's resources."],[],""],
 ["4.30","Deferred student loans",["Loans deferred for more than a year may generally be disregarded. Consider whether new or additional income will offset the expense once payments begin."],[],""],
 ["4.31","Judgments, federal debts, and tax liens",["Paid off, or documentation of a reasonable and approved payment agreement with a history of on-time payments."],[],""],
 ["4.32","Bankruptcies",["A bankruptcy on the applicant's (or spouse's) history does not in itself disqualify. Develop the facts, reasons and type of filing. Chapter 7: two years from discharge. Chapter 13: one year with all on-time payments and approval from the bankruptcy judge/trustee."],[],""],
 ["4.33","Foreclosures and short sales",["Foreclosures: apply the bankruptcy guidelines — generally a minimum of 24 months. Deed in lieu and short sales: develop complete information; if payment history was not affected before the event and the borrower voluntarily worked with the servicer, a waiting period may not be necessary; if forced, a more extended period showing restored credit is in order."],[],""],
 ["4.34","Collection accounts",["Unacceptable credit does not become acceptable by paying off collections before approval. VA considers overall history and may view collections unfavorably; an otherwise favorable history with an isolated unpaid collection can be acceptable. VA doesn't require collections be paid, but 5% of the balance must be added to the debts as a payment."],[],""],
 ["4.35","Consumer credit counseling",["Prior adverse credit + a CCC plan: satisfactory risk if 12 months' satisfactory payments and the agency approves the new credit. Good prior credit + CCC plan: neutral or even positive factor."],[],""],
 ["4.36","Marriage",["Married and using a VA loan in a community property state (AZ, CA, ID, LA, NV, NM, TX, WA, WI): VA requires qualification with both spouses' debts and a credit report for both, even if only one is on the loan."],[],""],
 ["4.37","Divorce",["Per the Lender's Handbook, VA will disregard delinquent payments made after responsibility was assigned to the ex-spouse in a divorce."],[],""],
 ["4.38","VA residual income",["Residual income is VA's cornerstone of underwriting. On DTI the only statement VA makes is that the veteran MUST have 120% residual income if DTI exceeds 41%. Handbook 26-7 Topic 4 §10.b: a ratio greater than 41% requires scrutiny unless (a) the ratio is over 41% solely because of tax-free income noted in the file — approvable with justification by the underwriter's supervisor, OR (b) residual income exceeds the guideline by at least 20%."],[],""],
 ["4.39","VA residual income requirements",["Residual income = the required net/discretionary income remaining after deducting expenses so there is enough for day-to-day costs. It varies by family size, region, and loan size. Deduct: federal and state income taxes, FICA, job expenses and other state-required deductions, maintenance/utilities at $0.14/sq ft, credit-report debt, child support, and day-care expenses."],[],""],
 ["4.40","Residual income charts",["Two tables — loans $79,999 and below, and $80,000 and above — by Northeast/Midwest/South/West and family size 1–5, with $75 (low table) or $80 (high table) per additional member up to a family of seven. The Residual calculator applies the right row."],[],""],
 ["4.41","Residual income — additional notes",["Tax-free income (VA disability, BAH/BAS, some Social Security, some disability pensions) can be grossed up 25% for DTI; however the grossed-up amount CANNOT be used in the residual calculation and must be backed out. Residual income is often the deciding factor on a marginal loan. Handbook Topic 4 §10.a calls it 'balance available for family support' — not to be used to automatically approve or reject, but reason enough on its own to deny. Every mortgage professional must complete the residual calculation on every VA application."],[],""]]},
{id:"c5",n:5,title:"The VA Appraisal",sub:"Value and MPRs",obj:["Reasonable value","Eligible and ineligible properties","The VA appraisal process including Tidewater, Notice of Value, and Reconsideration of Value","VA's Minimum Property Requirements and how to explain them"],sec:[
 ["5.1","VA appraisals — reasonable value",["'Reasonable value' is the figure a reputable, qualified appraiser, unaffected by personal interest, bias or prejudice, would recommend to a prospective purchaser as a proper price in light of prevailing conditions."],[],""],
 ["5.2","Reasonable value vs market value",["VA considers them synonymous; VA's definition of market value is consistent with Fannie Mae, Freddie Mac and major appraisal organizations."],[],""],
 ["5.3","Types of properties eligible for appraisal",[],["Existing construction","New construction","Proposed or under construction","Manufactured home classified as real estate","Other manufactured homes","Property to be altered/improved/repaired","Security for existing VA loan","Refinancing","Partial release of security","Foreclosure"],""],
 ["5.4","Properties not eligible for appraisal",["Properties not likely to meet MPRs:"],["Property in a badly deteriorated condition","Location-related problem","Non-VA-approved condo","Ownership is not fee simple"],""],
 ["5.5","Appraiser's approaches to value",["Sales comparison: VA relies exclusively on it except in very unusual circumstances (inadequate/nonexistent comps or an extremely unique property). Cost approach: may only support the sales comparison in final reconciliation. Income approach: not required for single-family."],[],""],
 ["5.6","Tidewater Initiative",["Since 2003, Tidewater gives a designated Point of Contact the chance to provide market evidence before the final URAR value is set. The appraiser alerts the person who ordered the appraisal (normally the lender) that value appears likely to come in under the sales price; the lender contacts both agents, who have 48 hours to provide any information to support the sales price."],[],"Have your comp package ready at contract so Tidewater is a two-hour task, not a two-day scramble."],
 ["5.7","Notice of Value (NOV)",["The Staff Appraiser Reviewer (SAR) employed by the lender reviews the appraisal and issues the NOV, setting the value and required repairs. SARs no longer have authority to change the appraiser's value but can and do inquire when something looks wrong — which can trigger the appraiser to change comps and the value. SARs can change the repairs required."],[],""],
 ["5.8","Reconsideration of Value (ROV)",["If the NOV is issued and value is still below price, the veteran can request an ROV — the veteran must be the one to request it, in writing (typically an email to the lender, who submits to the RLC). VA staff review the report, the submitted data, and VA's AMS market data."],[],""],
 ["5.9","Cancelling a VA appraisal",["Lenders must notify the fee appraiser and VA if a case is cancelled. No work done — no charge; partial work — a reasonable fee at the appraiser's discretion; report completed — the full fee is due."],[],""],
 ["5.10","Transfer of a VA appraisal",["Lenders must cooperate when a veteran changes lenders; the ordering lender transfers the case on the veteran's written request (email counts). A SAR of the original lender transfers the report and case number in WebLGY to another LAPP lender. The new lender should give the veteran their email, phone and VA Lender ID to include in the letter."],[],"An NOV issued by a SAR is not transferable — the new lender's SAR must review the appraisal and issue a new NOV."],
 ["5.11","Sending appraiser feedback",["Complaints go to the Construction & Valuation (C&V) department at VA. Appraisers with a track record of lateness or questionable techniques can be removed from the panel. Complaints must be factual (timeliness, support); a value question must be objective and well documented with support provided to the VA Valuation Officer at the time. Agents, lender and clients can each submit their own complaint."],[],""],
 ["5.12","Property requirements (MPRs)",["VA appraisals go beyond conventional by ensuring the home meets MPRs. Some are precise; others give room for interpretation. If a condition would impact safety, structural soundness or sanitation, the appraiser notes it and requires inspection and correction by a professional in that field with full disclosure to the veteran."],[],""],
 ["5.13","Minimum Property Requirements",["Existing and new construction: the property must be safe, structurally sound and sanitary, and meet standards acceptable for a permanent home in its locality. Proposed/under construction: built to the applicable building code, federal regulations, and HUD requirements."],[],""],
 ["5.14","Safe, sound, and sanitary",["Safe — the appraiser examines each part of the home for potential safety hazards. Sound — structural integrity; the appraiser cautiously evaluates structural weaknesses. Sanitary — rudimentary sanitation guidelines must be met for final approval."],[],"The MPR Safe/Sound/Sanitary guide on the MPR tab lists every item by category."],
 ["5.15","MPRs that impact VA purchases",[],["Mechanical systems","Heating","Electricity","Water supply","Sanitary facilities","Roof covering","Crawl space","Ventilation","Access","Drainage","Lead-based paint","Gas and petroleum pipelines or high-voltage electric transmission lines"],""],
 ["5.16","MPR variations and exemptions",["VA may modify MPRs where justified by conditions common to a geographic area or the site, or where compliance is impractical or impossible. An MPR for existing construction can be waived by the VA field office if: (1) a veteran is under contract, (2) veteran and lender request the exemption in writing, (3) the property is habitable from a safety/soundness/sanitation standpoint, and (4) VA is satisfied the nonconformity is accounted for by depreciation in the valuation."],[],""],
 ["5.17","Outside the appraiser's scope",["Whenever possible the appraiser notes any out-of-requirement condition and specifies the fix. Specialty areas (mold, foundations, roof cracks, etc.) are outside the appraiser's ability to judge — the appraiser notes the concern and requires a licensed contractor to assess whether it is truly unsafe, unsound or unsanitary and what correction is needed; a contractor letter is normally required."],[],""],
 ["5.18","Permitted vs non-permitted additions",["VA has no guideline on permits, but USPAP (which all appraisers follow) does. Appraiser options: (1) note unpermitted and indicate done in a workmanlike manner; (2) note unpermitted and NOT workmanlike; (3) note unpermitted and indicate the report will not be complete until permits are proven."],[],""]]},
{id:"c6",n:6,title:"VA Refinance Highlights",sub:"Callouts for IRRRLs and cash-out",obj:["VA cash-out Type I","VA cash-out Type II","VA Interest Rate Reduction Refinance Loan (IRRRL)","Refinance seasoning requirements"],sec:[
 ["6.1","VA cash-out refinance (any VA refinance besides the IRRRL)",["Primary residence only and must have a lien on the property. Type I — loan balance CANNOT increase. Type II — loan balance can increase; must meet a VA Net Tangible Benefit:"],["The new loan eliminates mortgage insurance","The term of the new loan is less than the current term","The interest rate is less than the current rate","The monthly P&I is lower than the current loan","The veteran's monthly residual income is higher as a result","The new loan pays off a construction loan","The new loan LTV is ≤ 90% of reasonable value","Refinancing an ARM into a fixed"],""],
 ["6.2","VA IRRRL",[],["Primary, second home, or investment property is allowed (previously occupied).","Non-credit qualifying vs credit qualifying (20% PITI increase triggers credit qualifying).","Cannot receive cash back.","Must meet Net Tangible Benefits: fixed→fixed 50 bps rate reduction and recoup within 36 months; fixed→ARM 200 bps reduction, recoup within 36 months, appraisal required if charging discount points; ARM→fixed no rate reduction required, recoup within 36 months.","If P&I increases and recoupment is not met, NO closing fees can be charged.","0.5% VA funding fee for non-exempt veterans."],"The IRRRL recoup/NTB tester is in Deep review → IRRRL."],
 ["6.3","IRRRL — borrowers obligated on the new loan",["Ten party combinations — unmarried veteran → veteran + new spouse (yes); veteran + spouse → divorced veteran alone (yes); → veteran + different spouse (yes); veteran alone → different veteran with substituted entitlement (yes); veteran + spouse → spouse alone, veteran died (yes); veteran + non-veteran joint obligors → veteran alone (yes); veteran + spouse → divorced spouse alone (no); unmarried veteran → spouse alone, veteran died (no); veteran + spouse → different spouse alone, veteran died (no); veteran + non-veteran → non-veteran alone (no)."],[],""],
 ["6.4","Seasoning requirements",["The note date of the refinance must be on or after the later of: the date 210 days after the first payment due date of the loan being refinanced, AND the date the borrower has made at least six monthly payments (may not prepay to meet it). Any interruption in payments before the initial six months resets the minimum seasoning."],[],"Use the Seasoning tool to compute the earliest note date."]]},
{id:"c7",n:7,title:"VA Assumptions",sub:"Release of Liability and Substitution of Entitlement",obj:["Release of Liability (ROL)","Substitution of Entitlement (SOE)"],sec:[
 ["7.1","Release of Liability (ROL)",[],["All VA loans are fully assumable with qualification — the process is called a Release of Liability.","Anyone (not necessarily a veteran) can assume; the process is handled by the servicer of the current VA loan.","The assumer pays a 0.5% VA funding fee (unless an exempt veteran) plus a processing fee.","The buyer assumes the remaining balance and remaining term.","If the purchase price exceeds the remaining balance, the buyer pays the seller the difference at closing.","VA allows secondary financing — see VA Circular 26-24-17: Secondary Borrowing Requirements on Assumption Transactions."],""],
 ["7.2","Substitution of Entitlement (SOE)",[],["If the veteran sells to another veteran, the buyer can substitute their entitlement for the seller's — Substitution of Entitlement.","Both seller and buyer must request it in writing during the assumption; after the servicer processes the ROL it goes to VA to process the SOE and transfer the full entitlement obligation to the buyer.","The buyer must have sufficient remaining entitlement to cover the original loan amount and the entitlement attached to that loan.","Occupancy is required by the assumer when substituting entitlement."],""],
 ["7.3","VA assumption pros & cons",["Pros: in a difficult market it can help a veteran seller who must move or face early termination (foreclosure); a low-rate VA loan is advantageous in a rising-rate market and a substantial sales factor; a very good option for a veteran who may never use entitlement again. Cons: without an SOE the veteran's entitlement stays tied to that home until the loan is paid in full (or sold) and only liability is removed; the assumer can let someone else assume in the future; a future assumer might default and the veteran's entitlement is gone unless the veteran repays VA's loss."],[],"The Assumptions tab has the seller strategies and the prospecting playbook."],
 ["7.4","Divorce situations",[],["A veteran may seek release from personal liability when the former spouse acquires the property through a legally binding separation agreement or divorce and the ex-spouse was jointly liable before the divorce — review Chapter 5 of the Handbook; standard ROL procedures (without an SOE the entitlement stays tied to the loan).","When the veteran is awarded the property, the ex-spouse may seek a Release of Liability: refer to the RLC of jurisdiction over the property's state to process a Non-Veteran Spouse (NVS) ROL; the servicer receives an NVS letter releasing the non-veteran spouse; the servicer may charge only $50 to amend its records; the servicer need not complete an ROL."],""]]}];
const MVLC_STEVE_NOTES=[["Where this guide and the dashboard meet","The MVLC is the industry's agent-and-LO certification — the deep review, course, QC auditor and calculators on this page go further on every topic, and the cites in this course point to the matching VANESSA tool."],["Numbers that date","County limits ($806,500 / $1,209,750 in the examples), the 2023–2024 stats, and the funding-fee schedule are the guide's print-date figures — refresh from FHFA/VA before quoting."],["What the exam keys on","Entitlement math (25% × CLL − used, × 4; DP = 25% of the shortfall), joint-loan fee averaging, residual-income tables and the 120% rule, allowable vs non-allowable fees vs the 4% concession cap, Tidewater 48 hours, ROV by the veteran in writing, seasoning 210 days + 6 payments, ROL vs SOE."]];
/* In-depth elaboration per section — practitioner layer on top of the guide text (why it matters, how to document, pitfalls, what to say). Keyed by section number. */
const MVLC_DEPTH={
"1.1":"The guaranty was designed as leverage, not charity: a partial guaranty lets a private lender lend 100% without MI because VA absorbs the first loss (today 25% of the loan). Everything downstream — no MI, residual income instead of a DTI cap, allowable-fee limits — flows from that 1944 design choice. When a seller's agent calls VA 'government money', correct it: it is private money with a federal guaranty.",
"1.2":"Use the mix, not just the totals. Purchase at 62% means most VA volume is competing on the open market against conventional offers; IRRRLs at 20% means a fifth of the program is streamline refis you can originate from your own past closings with no appraisal. Keep your own closed-loan stats next to these to prove your conversion rate to agents.",
"1.3":"The medians are your pre-approval credibility sheet: median DTI 43.8% shows VA approves above 41% routinely (via residual income); median assets of $19,819 shows VA buyers close with modest reserves; 18.8 days from case number to guaranty rebuts 'VA is slow'. Share the 60%-previous-owner figure with listing agents who assume VA buyers are first-timers.",
"1.4":"Each myth maps to a chapter. Train agents with the pairing: myth → section → one-sentence fact. Keep the Myths panel open in listing-agent calls; most objections to a VA offer are one of these ten.",
"1.5":"Program the RLC number (877-827-3702) into your phone; loan technicians answer eligibility, COE, funding-fee refund and appraisal/ROV questions. Subscribe to gov.delivery so circulars (fee changes, NTB rules, assumption second liens) reach you the day they publish. Lender Statistics lets you check a competitor lender's VA volume and days-to-close.",
"2.1":"Explain the guaranty in one line to borrowers: 'VA insures the lender against loss on part of your loan, which is why there's no down payment and no monthly MI.' Because VA 'rarely gets involved', almost all approvals are LAPP/automatic — the lender's underwriter is the decision maker, so advocacy is with the underwriter, not VA, except on prior-approval files (joint vet/non-vet, some restoration cases).",
"2.2":"'Max guaranty 25%' is the reason full-entitlement veterans have no loan limit since 2020 — the lender always gets 25% coverage. 'Fully amortizing only' means no interest-only and no negative amortization; temporary buydowns are fine because the note still amortizes. 'Finance the funding fee' changes LTV — tell the veteran the base loan and the total loan separately.",
"2.3":"The five requirements are the five sections of the Loan Analysis (VA 26-6393): eligibility/COE, purpose, occupancy certification, credit, and income/residual. Build every file in that order and a VA underwriter reads it in that order.",
"2.4":"Eligible purposes include simultaneous purchase-and-improve (alteration/repair) and energy-efficiency improvements added to any purchase or refinance (EEM up to $6,000 without additional qualifying in most cases). Condo must be on VA's approved list — check before writing the offer, and if not approved, ask the HOA for the condo package to submit for approval (expect weeks).",
"2.5":"The business-use test is three parts: primarily residential, no more than one business unit, and the non-residential area doesn't detract. A duplex with a storefront fails; a home with a detached office usually passes. Land-only is out unless tied to a VA construction loan with a VA-approved builder.",
"2.6":"Know the adjacent programs so you never say 'VA can't': SAH/SHA grants for adapted housing (combine with the loan), NADL on trust land, state programs like CalVet (its own loan, not VA guaranty), and assumptions. The deep-review tabs on this page cover EEM, construction/one-time-close and assumptions in detail.",
"2.7":"'Any part during wartime' is generous: 90 days of active duty with one day overlapping a wartime period qualifies. Peacetime needs 181 continuous days. Active duty for training (ADT) generally does not count toward these thresholds unless it was Title 10 — this is where Guard/Reserve files get kicked back.",
"2.8":"Post-1980 enlistees who separated before 24 months are the most common surprise ineligibility. Exceptions: early-out for hardship, convenience of the government, reduction in force, a service-connected disability, or completion of the full period called to active duty. Pull the DD-214 narrative reason (block 28) and separation code before you quote anyone.",
"2.9":"Six 'good years' means six anniversary years each with at least 50 points under VA's reading (the guide simplifies to 15 membership + 1 training). Honorable discharge from the Reserve component, or still serving. Title 10 activation can qualify a Guard/Reserve member under the active-duty rule instead, with a DD-214 for that period — often faster than the six-year path.",
"2.10":"Surviving spouses get a COE via VA Form 26-1817 (not 26-1880) and are funding-fee exempt (codes 06/07). The remarriage-after-57 rule since 12/16/2003 is frequently missed by lenders. Confirm DIC receipt — it also proves the fee exemption.",
"2.11":"'Eligibility never expires' is the sentence to put in every veteran outreach piece. A 1970s Vietnam-era veteran who never used the benefit has full entitlement today. One day of service with a service-connected discharge is enough — ask for the DD-214 reason and the VA rating letter.",
"2.12":"Order the COE at first contact, before the pre-approval letter. WebLGY returns most automatically in seconds; if it says 'unable to determine', upload the DD-214 and submit 26-1880 electronically through WebLGY — don't mail it. The COE date must be before the note date and the entitlement shown must cover the loan.",
"2.13":"Match the document to the status and read it: DD-214 Member-4 (character of service, net active service, narrative reason); Statement of Service on letterhead, dated within 120 days, signed by the commander/adjutant/personnel officer, with name, SSN/DOD ID, DOB, entry date, lost time, and the unit; NGB 22 + NGB 23 points; reserve points statements for the six-year check.",
"2.14":"Standard Form 180 goes to the NPRC in St. Louis; eVetRecs is the online version. Expect weeks — order it the day a veteran says 'I can't find my DD-214'. VA.gov can download many VA letters (benefit summary, rating) instantly, which also proves funding-fee exemption.",
"2.15":"The code tells you fee class and era at a glance. 05 means subsequent use (3.3% at zero down) unless exempt. 11 (Selected Reserve without Title 10 service) once carried a higher fee; current schedules charge Reserve/Guard the same as regular — treat the guide's '.25%' note as historical.",
"2.16":"Add up the 'Entitlement Charged' column for every Active loan — that is the number you subtract from 25% of the county limit. 'Paid in Full/No Restoration' loans still count as charged until restoration is requested. For Compromise and Foreclosure lines the charged amount stays until VA's loss is repaid (the RLC can quote the payoff).",
"2.17":"Read conditions before you quote a fee. 'Non-Exempt — In Development' on an active-duty member means close after discharge or lose the exemption and the refund. 'Subsequent use' shows the 3.3% applies. The funding-fee refund paragraph is a prospecting script: any past client whose rating effective date pre-dates their closing may be owed a refund through their servicer.",
"2.18":"Since 1/1/2020 (Blue Water Navy Act) full entitlement = no limit; the lender sets its own ceiling (jumbo VA overlays commonly $1.5M–$2M+). Partial entitlement veterans are capped by the FHFA one-unit limit for the county where the new home sits — not the county of the existing loan.",
"2.19":"'Four times available entitlement' is the whole formula. Available entitlement = 25% × county limit − entitlement charged. If the result is negative, there is no entitlement in that county and the veteran needs 25% down of the price (or restoration).",
"2.20":"Basic entitlement $36,000 covers loans to $144,000; above that, bonus entitlement takes over. On a COE 'basic entitlement is $0' with an active loan simply means the basic $36,000 is used — look to the county limit for the bonus portion.",
"2.21":"Bonus entitlement moves with the conforming limit each January; a veteran who was short last year may have enough this year with no action. Re-run the calculation every January for every partial-entitlement prospect.",
"2.22–2.23":"Example 1 shows a 1990 foreclosure charge of $36,000 still leaves $165,625 of bonus entitlement in a high-limit county. Example 2 shows an expensive active loan ($318,750 charged) wipes out entitlement in a standard-limit county — the fix is restoration (sell/refinance to conventional), a 25% down payment, or a non-VA program.",
"2.24":"VA requires 25% of the shortfall, not 25% of the price: DP = 0.25 × (price − 4 × remaining entitlement). The down payment can come from gift funds unless the price exceeds reasonable value. Funding fee drops to 1.50% or 1.25% if the DP reaches 5% or 10% of price — check whether the required DP crosses those thresholds.",
"2.25–2.26":"Use the Entitlement calculator with the guide's numbers to see each step; then swap in the current FHFA limit for your county — the answers change every year.",
"2.27":"Three restoration paths: basic (sold and paid in full — automatic on request with the closing statement), one-time (paid in full, home kept — used once, after which all VA-financed homes must be sold for future restorations), and rapid restoration for sell-and-buy transactions (lender submits the payoff/HUD before funding of the new loan). Submit through WebLGY with the HUD-1/CD of the sale.",
"2.28":"Script: 'The funding fee replaces mortgage insurance — one-time, financeable, and gone the day you're rated for a service-connected disability.' Check exemption first, then down-payment reduction, then seller payment inside the 4%.",
"2.29":"Fee math on a $500,000 zero-down first use: 2.15% = $10,750 (financed → $510,750 loan). Subsequent use 3.3% = $16,500 — a 5% down payment ($25,000) drops it to 1.50% ($7,125), often a better use of cash than a rate buydown. Verify the current schedule on VA.gov; it changes by statute.",
"2.30":"Exemption proof: COE says Exempt, or the VA benefit summary/rating letter, or VA 26-8937 for active duty/pending claims. A 10% rating is enough. Veterans receiving retired pay in lieu of compensation are exempt; those with a pending claim are not exempt until rated.",
"2.31":"If the COE is wrong, don't close non-exempt and hope for a refund — upload the rating letter to WebLGY and request a corrected COE; it usually comes back in days. Refunds after closing go through the servicer and can take months.",
"2.32":"Ask every active-duty applicant the pre-discharge-claim question and document the answer. If the member will separate soon with a pending claim, closing after discharge (once rated) can save thousands; closing before means no exemption and no refund.",
"2.33":"Occupancy is certified on the 26-1820 at closing — twice (intent at application, confirmation at closing). Investment intent is fraud; multi-unit is fine if one unit is the veteran's home.",
"2.34":"Document delayed occupancy with the event and the date (PCS orders, retirement date, completion of renovations). Over 12 months is not reasonable; between 60 days and 12 months needs the certification and the specific future event.",
"2.35":"A deployed or remote-stationed veteran whose spouse will live in the home meets occupancy. Dependent-child occupancy requires the attorney-in-fact or guardian to certify on 26-1820. The spouse does not need to be on the loan to satisfy occupancy.",
"2.36":"Deployment is TDY status; the veteran can buy near the permanent duty station even though no one occupies until return. Pair with a specific POA for the closing documents.",
"2.37":"Retirement within 12 months with the retirement date documented; delayed occupancy for repairs where the veteran moves in on completion; intermittent occupancy where the veteran's work keeps them away but the home remains the primary residence (no other primary).",
"2.38":"Spouse rules are the most misunderstood: veteran + non-veteran spouse is an ordinary VA loan (spouse's income and credit used, no joint-loan rules). Veteran + unmarried partner is a joint loan requiring prior approval. Two married veterans both using entitlement is a joint loan without prior approval.",
"2.39":"Both veterans occupy; VA splits the guaranty equally unless they elect otherwise in writing. Funding fee is computed on each veteran's half with each one's own class (first use/subsequent/exempt). Processed LAPP — no VA prior approval.",
"2.40":"Fee averaging: (3.3% × $350,000 + 0% × $350,000) / $700,000 = 1.65%. Each veteran only needs 25% of their own half in available entitlement ($87,500) — a veteran keeping another VA loan can still qualify if the remainder covers that.",
"2.41":"Prior approval means the full package goes to the RLC (expect 1–3 weeks); build that into the contract timeline. The non-veteran's half is unguaranteed, so a 25% total investment (guaranty + down payment) is needed for GNMA pooling — that is the ~14.3% down payment. Only the veteran's income/debts qualify the veteran's share; the non-veteran qualifies separately.",
"2.42":"Reproduce it in the Joint calculator: a 50/50 split with the veteran's 1.25% fee financed yields a 14.209% down payment ($99,464) and an average fee of .625%. Change the split to 70/30 to see how the down payment falls as the veteran's share rises.",
"3.1":"Non-allowables are a closing-table problem if nobody planned for them. Write 'seller to pay buyer's VA non-allowable fees' into the RPA, and ask the lender for its VA non-allowable list at pre-approval. Overpar pricing cannot cover them — a true lender credit can.",
"3.2":"Three buckets the veteran may pay: itemized allowables, the 1% origination (or itemized equivalents), and reasonable discount points. Anything else charged to the veteran must be paid by another party.",
"3.3":"Brokerage fees are allowable only under the post-NAR-settlement temporary variance (Circular 26-24-14 and extensions) — verify the current circular before letting a veteran pay a buyer-broker fee. Prepaids and the funding fee are allowable and financeable (fee) or seller-payable (prepaids).",
"3.4":"If the lender charges a full 1% origination, it cannot also charge processing, underwriting, doc prep, or application fees. If it charges less than 1%, it may itemize up to the 1% total. Compare lenders on this line.",
"3.4b":"Attorney fees for anything other than title work, prepayment penalties and the HUD/FHA builder inspection fee are never the veteran's. Most lenders also treat processing/underwriting/application fees as non-allowable because they sit inside the 1%.",
"3.5":"The seller may pay discount points without them counting as concessions (up to about two points). Overpar/premium pricing is the veteran's own money — it can pay allowable costs and prepaids but not non-allowables.",
"3.6":"Two separate buckets on every VA offer: (1) standard non-recurring closing costs — unlimited, paid by anyone; (2) seller concessions — capped at 4% of reasonable value. Prepaids are a concession item when the seller pays them; title, escrow, recording, appraisal are not.",
"3.7":"Concession = value the seller is not customarily required to provide. Paying the buyer's funding fee, prepaids, debt payoff, appliances, or temporary buydown escrow all count toward 4%. The cap is on reasonable value, not price.",
"3.8":"On a $600,000 home: seller pays $12,000 of non-recurring costs (not a concession), pays the $12,900 funding fee (concession), funds a $9,000 2-1 buydown escrow (concession) — total concessions $21,900 = 3.65%, under 4%. The Deep review → Fees tab classifies each line for you.",
"4.1":"Military POAs often come from the base legal office; VA requires the veteran to sign the application and contract or use a specific POA naming the property, price, terms, entitlement use, and occupancy intent. The alive-and-well check at closing must be documented in the file (an email or call log from the command within days of closing).",
"4.1b":"For deployed borrowers, the lender obtains confirmation from the command that the veteran is alive and not MIA, dated as close to funding as possible. Missing it is a guaranty-denial risk the lender will not take — plan it with the POA.",
"4.2":"VA income analysis is about continuance and sufficiency, in that order. Document continuance (ETS, orders, employer letters) before you compute ratios.",
"4.3":"Lender responsibility is why the underwriter is strict on verifications: the lender certifies to VA. Your job is to deliver a complete, internally consistent file — mismatched LES and orders dates are a common kickback.",
"4.4":"Common overlays: minimum FICO 580–640, max DTI 50–55% even with residual, no manual underwrites, no manufactured homes, no 2–4 units without landlord history. When a file dies on an overlay, broker it elsewhere — the VA rule itself allows it.",
"4.5":"Two years validated or AUS-reduced to one year — but residual and continuance still apply. Keep the AUS findings in the file as the basis for reduced documentation.",
"4.6":"Pay grade drives base pay (DFAS tables), BAH (grade + zip + dependents) and BAS (enlisted vs officer flat rates). Confirm grade from the LES, not from what the borrower says their rank is after a recent promotion.",
"4.7":"Use the most recent LES; the 120/180-day age rule is to the note date for automatic loans. Add a Statement of Service or orders to show continuance.",
"4.9":"Read the LES in this order: ETS → entitlements (base, BAS, BAH) → allotments (hidden debts) → deductions (TSP loan, garnishments, AFRH) → remarks (BAH zip/dependents, TSP loan balances). Mid-month pay is a draw, not income.",
"4.10":"ETS inside 12 months is the first thing to check. Officers' 'ETS' shows as a placeholder (e.g., 888888). BAH is counted at the full amount (tax-free; gross-up for DTI only). Special pays (jump, sea, flight, hazard) need orders showing continuance.",
"4.11":"Drill pay for Guard/Reserve is usable with a two-year history and continuance; if not determinable it only offsets short-term debt. Split allowances into taxable/tax-free for correct federal/state tax deductions in the residual calculation.",
"4.12":"Recently discharged veterans: use the DD-214 MOS and the new employer's job description to argue related experience; separation pay and terminal leave are one-time; retirement pay (20+ years) is permanent income and often tax-free in part (disability offset).",
"4.13":"Two years of employment history, not two years at the same job — job changes within a field are fine with explanation.",
"4.14":"Less than 12 months can work with training/education in the field, a written employer probability-of-continuance statement, and a prior history in the same line of work (military MOS counts).",
"4.15":"Keep the table visible when structuring: overtime and second jobs need two years; GI Bill housing allowance is never income; public assistance needs three years' continuance.",
"4.16":"Court order or signed, recorded agreement plus 12 months of receipt (bank statements). Child support ending within three years cannot be used; alimony with a sunset date inside three years is out.",
"4.17":"VA disability compensation is stable, tax-free, and often grossed up 25% for DTI — but never for residual. Dividends/interest need a two-year history and continuing assets.",
"4.18":"Community-property-state rule (AZ, CA, ID, LA, NV, NM, TX, WA, WI): the non-borrowing spouse's debts count and a credit report is pulled, but the spouse's income is not used unless the spouse is on the loan. Tell California veterans this upfront — it surprises them.",
"4.19":"Two years of returns, YTD P&L and balance sheet; declining income needs explanation; the business must show it can continue. VA does not require audited statements.",
"4.20":"Departing residence → offset only (no positive rental income). Multi-unit subject → 6 months PITI reserves + landlord experience/management contract, use 75% of market rent. Existing rentals → on returns + 3 months PITI each. Boarder income needs two years on returns.",
"4.21":"Verified liquid assets: two months' statements, large deposits sourced. If price exceeds reasonable value, the overage must be the veteran's own funds (not gift) — gift funds can cover closing costs and ordinary down payment.",
"4.22":"Reserves are a compensating factor even when not required; show them. Retirement accounts count at the vested balance less penalties per lender policy.",
"4.23":"Gift letter + proof of transfer, or donor's wire to escrow, or the CD showing receipt. Donors cannot be the agent, builder, seller, or lender. Gifts of equity from a family seller are allowed with the sales contract reflecting it.",
"4.25":"Credit report items: 12–24 months is the window VA weights; older derogatories with a clean recent pattern are usually fine. Verify all significant obligations, including those not on the report (child support, private loans, allotments).",
"4.26":"No VA minimum FICO means a 560 file can be manually underwritten at a lender without an overlay. Build residual income and compensating factors; VA approval is a judgment call by the underwriter.",
"4.27":"Non-traditional credit: 12 months of rent, utilities, phone, insurance, and child-care payments — three or more references. Rent is the strongest one.",
"4.28":"Verify the payment amount on the court order; if payments are delinquent, treat as a derogatory and explain.",
"4.29":"Ten-month rule: debts with 10 or more payments remaining count; fewer than 10 may be excluded unless the payment is large relative to income. Pay-downs to under 10 months are allowed with documentation.",
"4.30":"Deferred over 12 months from closing → can be excluded; otherwise lenders use the actual payment or a percentage of balance (commonly 5% / 12). Income-based repayment plans with a documented payment are acceptable.",
"4.31":"Federal debts (defaulted student loans, VA overpayments, IRS liens) must be paid, or in a repayment plan with history — CAIVRS is checked on every VA file; a hit must be cleared.",
"4.32":"Chapter 7: two years from discharge, re-established credit. Chapter 13: 12 months of on-time plan payments plus trustee approval to incur the debt; can close while still in the plan.",
"4.33":"Foreclosure: generally 24 months, measured from the date title transferred. A prior VA foreclosure also reduces entitlement until VA's loss is repaid. Short sale/deed in lieu with no prior delinquency and cooperation can avoid a waiting period.",
"4.34":"Collections: not required to be paid; 5% of the balance per month is added to debts unless a payment plan documents less. Medical collections are generally disregarded by lenders. Isolated collections with otherwise good history are acceptable.",
"4.35":"Consumer credit counseling plan: 12 months of on-time plan payments plus the agency's written approval of the new mortgage. A plan with good prior credit is neutral-to-positive.",
"4.36":"Community property: pull the spouse's credit, count the spouse's debts, but you may not use the spouse's income unless they are on the loan. Explain this at application in CA/AZ/NV/WA/TX files.",
"4.37":"Divorce decree assigning a debt to the ex-spouse: VA disregards later delinquencies on that debt; the lender needs the decree and proof the ex-spouse is paying or the debt was awarded.",
"4.38":"Residual 120% rule: compute the table amount, multiply by 1.2 — if the veteran clears it, a 41%+ DTI is justified. The second path (tax-free income causing the ratio) needs the supervisor's sign-off. Put both arguments in the UW Advocacy memo.",
"4.39":"Compute residual by hand on every file: gross income − federal/state tax − FICA − subject PITI − HOA − maintenance (0.14 × sq ft) − debts − child support − child care = residual. Day care is included by most lenders when disclosed.",
"4.40":"Example: family of 4 in California, $500,000 loan → West, high table, $1,117. At 41%+ DTI the target is $1,340 (120%). A family of 6 adds $80 → $1,238 ($1,486 at 120%).",
"4.41":"Gross-up goes in the DTI column only. Back it out before residual. On marginal files the residual number is what the underwriter writes in the approval justification, so lead with it.",
"5.1":"Reasonable value is a market-value opinion; the VA appraiser also certifies MPR compliance. Order the appraisal in WebLGY the day the contract is accepted — the case number is required and the appraiser is assigned by VA, not chosen by the lender.",
"5.2":"Because VA and conventional definitions match, a prior conventional appraisal on the property is useful Tidewater evidence (it cannot be converted to VA, but it supports value).",
"5.3":"Manufactured homes must be on a permanent foundation and classified as real estate; proposed construction needs plans/specs and a builder ID. 'Security for existing VA loan' and 'partial release' are servicing-side appraisals.",
"5.4":"Ineligible before you order: non-approved condo (check the VA condo list), leasehold not meeting VA's term rules, badly deteriorated structure, and location problems (airport clear zones, high-voltage lines over the dwelling).",
"5.5":"Sales comparison only — if the appraiser leans on cost or income approach for a single family, that is grounds for an ROV argument. Unique properties (log homes, mixed use) are where this bites.",
"5.6":"Tidewater is a 48-hour window: the lender's point of contact gets the call, both agents can supply comps and documentation, but no one may argue value with the appraiser directly. Have three closed comps, pending sales, and a cost-to-cure analysis ready at contract.",
"5.7":"The NOV is the lender's document (SAR) and lists required repairs, conditions, the value, and the expiration. Review it the day it issues — repair requirements found in the NOV are the seller negotiation list.",
"5.8":"ROV: the veteran requests it in writing (email to the lender is fine); the lender's SAR submits to the RLC with new comps/data. Target 3 better comps and errors in the report; opinions don't move value, data does.",
"5.9":"Cancellation fees follow the work done; if the deal falls through before inspection, cancel in WebLGY immediately to avoid a full fee.",
"5.10":"Appraisal transfers are the veteran's right. Give the veteran a one-paragraph email template: 'I am changing lenders; please transfer VA case # to [lender, VA ID, contact].' The new SAR issues a new NOV.",
"5.11":"Appraiser complaints: factual, documented, to the RLC's Construction & Valuation unit — timeliness (late beyond the state's timeliness days), unsupported adjustments, wrong comps. Anyone in the transaction can file.",
"5.12":"MPR findings require correction by the appropriate professional and a re-inspection (VA 26-1839 compliance inspection report) before closing unless an escrow holdback is approved for weather-related exterior items.",
"5.13":"Existing homes: safe, sound, sanitary. New construction: code + federal regulations + HUD; builder warranty or 10-year protection plan, termite treatment certification, and builder ID.",
"5.14":"The three words are the framework for every repair negotiation: ask 'is it safety, structure, or sanitation?' If none, it is a cosmetic item the appraiser should not require.",
"5.15":"Typical hits: peeling paint on pre-1978 homes (lead-based paint), missing handrails, inoperable heating, roof with less than remaining economic life, no permanent heat source, crawl-space moisture, wells/septic certifications, private road maintenance agreements.",
"5.16":"MPR waivers exist — regional conditions (no central heat in mild climates) or impractical compliance. Request in writing through the lender with the veteran's acknowledgment; the RLC decides.",
"5.17":"When the appraiser calls for a roof, foundation, or mold inspection, hire the licensed trade promptly; their letter stating the item is safe/sound/sanitary (or the repair invoice) clears the condition.",
"5.18":"Unpermitted additions: ask the appraiser's option early. Workmanlike-and-noted is the common outcome; 'report incomplete until permits proven' can kill a timeline — pull permits from the county portal before the appraisal.",
"6.1":"Type I cash-out (rate/term) and Type II (balance increases) both need an appraisal, full credit qualifying, and one of the eight NTB tests — plus the recoupment and loan-comparison disclosures. LTV up to 100% of reasonable value including the funding fee (lender overlays often 90%).",
"6.2":"IRRRL checklist: existing VA loan, rate drop (50 bps fixed-to-fixed), recoupment of allowable costs within 36 months, 210 days/6 payments seasoning, no more than 2 discount points financed, prior occupancy certification, 0.5% fee unless exempt. No appraisal, no income verification on non-credit-qualifying files.",
"6.3":"The parties table is about liability continuity: the new loan must keep a veteran (or surviving spouse of the original obligor) on it; a non-veteran or ex-spouse alone cannot IRRRL.",
"6.4":"Seasoning is measured from the first payment due date of the loan being refinanced; the note date of the new loan must be at least 210 days after that and after six full monthly payments. Prepaying does not count. Use the Seasoning tool before you lock.",
"7.1":"ROL through the servicer: 45–90 days typical, qualification like a new loan, 0.5% fee, servicer processing fee capped by VA. Price above balance is paid in cash or with a second lien per Circular 26-24-17. Agents must know the servicer, not the originator, runs the assumption.",
"7.2":"SOE protects the seller's entitlement; requires a veteran buyer with enough entitlement to substitute and who will occupy. Both parties request it in writing; VA processes after the servicer's ROL.",
"7.3":"Seller script: 'If a veteran assumes with SOE, your entitlement comes back; if a civilian assumes, you get released from liability but your entitlement stays tied up until that loan is paid.' Price the rate advantage into the offer.",
"7.4":"Divorce: the veteran who leaves can get an ROL if the ex-spouse was already on the loan; the non-veteran ex-spouse who leaves gets an NVS release through the RLC with a $50 servicer fee. Without SOE the veteran's entitlement stays on the home even after the ROL."};
/* References & tools */
const MVLC_FORMS=[["VA 26-1880","Request for a Certificate of Eligibility — when WebLGY cannot auto-issue; attach proof of service"],["VA 26-1817","Request for Determination of Loan Guaranty Eligibility — Unmarried Surviving Spouses"],["VA 26-8937","Verification of VA Benefits — exempt status, pending pre-discharge claims, VA indebtedness"],["VA 26-1820","Report and Certification of Loan Disbursement — occupancy certification at closing"],["VA 26-6393","Loan Analysis — the underwriter's worksheet (income, debts, residual, ratios)"],["VA 26-0592","Counseling Checklist for Military Homebuyers — required for active-duty borrowers"],["VA 26-8923","IRRRL Worksheet — maximum loan amount on a streamline"],["VA 26-1805","Request for Determination of Reasonable Value — appraisal request (WebLGY)"],["VA 26-1802a / HUD 92900-A","Addendum to the Uniform Residential Loan Application — VA/HUD certifications"],["VA 26-0286","VA Loan Summary Sheet — submitted with every guaranty request"],["VA 26-1839","Compliance Inspection Report — repairs/MPR re-inspection"],["VA 26-8320 / 26-8320a","Certificate of Eligibility (the COE itself, and the surviving-spouse version)"],["DD-214 (Member-4)","Certificate of Release or Discharge from Active Duty"],["NGB 22 / NGB 23","National Guard separation report / retirement points"],["Statement of Service","Letterhead letter from the command for active-duty applicants"],["SF-180","Request Pertaining to Military Records (NPRC)"],["VA 26-1859","Warranty of Completion of Construction (new construction)"],["Form 21-526EZ","Application for disability compensation — relevant when a client is filing a claim that would create a funding-fee exemption"]];
const MVLC_SYSTEMS=[["WebLGY (VA Loan Guaranty portal)","Lender system: COE requests/updates, appraisal ordering and case numbers, restoration, appraisal transfers, guaranty submission, funding-fee payment"],["VA.gov / eBenefits","Veteran self-service: COE, benefit letters, rating letters, DD-214 requests, condo/loan-limit lookups"],["VALERI","VA servicing system — assumptions (ROL/SOE), loss mitigation; your servicer contact works here"],["VA AMS (Appraisal Management Service)","VA market data used on ROV reviews — know that the RLC sees MLS-level data"],["LGY Hub / VA Lender Resources","Lender resources, Lenders Handbook chapters, circulars, condo approval list, loan-limit tables"],["FHFA loan limits","Annual one-unit county limits used for partial-entitlement math"],["DFAS myPay / pay tables","LES retrieval for active-duty clients; current base pay/BAS; BAH via DoD travel site"],["CAIVRS","Federal delinquency check — every VA file; clears VA/FHA/USDA/SBA/education debt hits"],["VA condo lookup (lgy.va.gov)","Approved condo projects — check before writing a condo offer"],["milConnect / DEERS","Dependents and benefits verification; proof of enrollment"],["National Personnel Records Center (eVetRecs)","Replacement DD-214s and service records"]];
const MVLC_HANDBOOK=[["Ch 1","Lender approval — LAPP/automatic authority, SAR"],["Ch 2","Veteran's eligibility and entitlement — COE, restoration"],["Ch 3","The VA loan and guaranty — purposes, maximum guaranty, joint loans, occupancy"],["Ch 4","Credit underwriting — income, residual income tables, debts, credit, compensating factors"],["Ch 5","How to process VA loans and submit for guaranty — forms, prior approval"],["Ch 6","Refinancing loans — IRRRL, cash-out Type I/II, NTB, seasoning"],["Ch 7","Loans requiring special underwriting, guaranty and other considerations — EEM, construction, manufactured, joint"],["Ch 8","Borrower fees and charges and the VA funding fee — allowables, 1% rule, non-allowables, exemptions"],["Ch 9","Legal instruments, liens, escrows and related issues — assumptions, secondary financing"],["Ch 10","Appraisal process — Tidewater, NOV, ROV, transfers"],["Ch 11","Appraisal requirements — MPRs"],["Ch 12","Minimum Property Requirements (detail)"],["Ch 13","Value notices and property eligibility"],["Ch 14","Fee appraisers and compliance inspectors — complaints, timeliness"],["Ch 15","Lender oversight and audit"],["Ch 16","Common interest communities (condos/PUDs)"],["Ch 17","Title and lien requirements"]];
const MVLC_CIRC_TOPICS=[["Funding-fee schedule changes","Search circulars for 'funding fee' — the 2.15/3.3/0.5 schedule is set by statute and updated by circular"],["IRRRL / cash-out NTB and recoupment","Search 'net tangible benefit' and 'recoupment' — defines which fees count toward the 36-month test"],["Assumption secondary financing","VA Circular 26-24-17 (cited in the guide): second liens on assumption transactions"],["Buyer-broker fees (temporary variance)","Search 'buyer-broker' — the post-NAR-settlement allowance letting veterans pay broker compensation; check expiration/extension"],["Appraisal timeliness and fees by state","Published on the RLC appraisal pages; used in the Timelines tab of this dashboard"],["Loan limits for partial entitlement","Annual circular adopting FHFA one-unit limits"],["Disaster circulars","Re-inspection requirements after a federally declared disaster in the property's county"]];
const MVLC_TEMPLATES=[
["ROV request (from the veteran)",(a)=>`To: ${a.lender||"[Lender]"} — VA case ${a.caseNo||"[VA case #]"}\n\nI am the veteran borrower on the above VA case. The Notice of Value of ${a.nov||"[$NOV value]"} is below the contract price of ${a.price||"[$price]"}. I request a Reconsideration of Value.\n\nSupporting data attached:\n1. ${a.comp1||"[Comp 1 — address, close date, price, why it is more similar]"}\n2. ${a.comp2||"[Comp 2]"}\n3. ${a.comp3||"[Comp 3]"}\nErrors/omissions noted in the report: ${a.errors||"[square footage, condition, adjustments, pending sales omitted]"}\n\nPlease submit this request and the attached data to the Regional Loan Center.\n\n${a.vet||"[Veteran name]"}\n${a.date||new Date().toLocaleDateString()}`],
["Appraisal transfer (veteran to original lender)",(a)=>`To: ${a.oldLender||"[Original lender]"}\n\nI am changing lenders for my VA purchase. Please transfer VA case ${a.caseNo||"[VA case #]"} and the appraisal report in WebLGY to:\n\nLender: ${a.lender||"[New lender]"}\nVA Lender ID: ${a.lenderId||"[VA ID]"}\nContact: ${a.contact||"[name, email, phone]"}\n\nThank you,\n${a.vet||"[Veteran name]"}\n${a.date||new Date().toLocaleDateString()}`],
["Rapid restoration request (lender to RLC via WebLGY note)",(a)=>`Veteran: ${a.vet||"[Name]"} — COE ref ${a.coe||"[ref #]"}\nPrior VA loan ${a.priorLoan||"[loan #]"} on ${a.priorAddr||"[address]"} is being paid in full through the sale closing on ${a.saleDate||"[date]"}. Closing disclosure/settlement statement attached showing payoff.\nThe veteran is purchasing ${a.newAddr||"[new address]"} with a scheduled closing of ${a.newDate||"[date]"}.\nPlease restore entitlement so the new COE reflects full entitlement prior to funding. Contact: ${a.contact||"[LO name, phone, email]"}`],
["Statement of Service request (to the command)",(a)=>`Request for Statement of Service — ${a.vet||"[Member name]"}, ${a.grade||"[grade]"}, DoD ID ${a.dod||"[xxxx]"}\n\nFor VA home-loan eligibility, please provide on command letterhead, signed by the commander, adjutant or personnel officer:\n• Full name, SSN/DoD ID, date of birth\n• Date of entry on current active-duty period and any lost time\n• Expected ETS/separation date (if applicable) and confirmation of eligibility to re-enlist\n• Name of the command/unit and contact for verification\nDated within the last 120 days. Thank you.\n${a.contact||"[LO name, NMLS, phone, email]"}`],
["Letter of explanation — intent to re-enlist (member)",(a)=>`To: ${a.lender||"[Lender]"}\n\nMy current Expiration Term of Service is ${a.ets||"[date]"}, which is within 12 months of my planned closing. I intend to re-enlist/extend and remain on active duty. A Statement of Service confirming my eligibility to re-enlist is attached. ${a.extra||""}\n\n${a.vet||"[Member name]"}, ${a.grade||"[grade]"}\n${a.date||new Date().toLocaleDateString()}`],
["Substitution of Entitlement request (seller + buyer)",(a)=>`To: ${a.servicer||"[Servicer]"} — VA loan ${a.loanNo||"[loan #]"}, ${a.addr||"[property]"}\n\nSeller ${a.seller||"[seller veteran]"} and buyer ${a.buyer||"[buyer veteran]"} request that, upon approval of the assumption and Release of Liability, the buyer's VA entitlement be substituted for the seller's (Substitution of Entitlement). Buyer's COE attached showing available entitlement of ${a.ent||"[$]"}, which covers the entitlement charged on this loan. The buyer will occupy the property as a primary residence.\n\nSeller signature: ____________  Buyer signature: ____________  Date: ${a.date||new Date().toLocaleDateString()}`],
["Tidewater comp package cover (listing/buyer agent to lender POC)",(a)=>`Tidewater response — ${a.addr||"[subject address]"}, VA case ${a.caseNo||"[VA case #]"}\nContract price ${a.price||"[$]"}. Submitted within the 48-hour window.\n\nClosed comparables:\n1. ${a.comp1||"[address · close date · price · sq ft · why comparable]"}\n2. ${a.comp2||"[...]"}\n3. ${a.comp3||"[...]"}\nPending/under contract: ${a.pending||"[address · list/contract price]"}\nCondition/upgrades with costs: ${a.upgrades||"[list]"}\nMarket note: ${a.market||"[days on market, list-to-sale ratio, multiple offers]"}\nSubmitted by ${a.contact||"[agent, brokerage, phone]"}`]];
const MVLC_CHECKLISTS={"Active-duty service member":["COE (WebLGY) — confirm funding-fee status; ask about pre-discharge claim (26-8937 if yes)","Statement of Service on letterhead ≤120 days","Most recent LES (≤120 days to note; 180 new construction) + ETS check (12-month rule)","Orders if PCS; deployment letter if applicable","VA 26-0592 counseling checklist (signed)","Specific or general POA if the member cannot attend; alive-and-well confirmation at closing","Occupancy plan: self, spouse, or dependent child (26-1820 certification)"],"Discharged veteran":["DD-214 Member-4 (character of service, narrative reason)","COE — review entitlement charged and conditions","Funding-fee exemption proof (rating letter/benefit summary) if applicable","Two years employment history; recently discharged → MOS-to-job continuity letter","Residual income computed by hand with the right region/table","Prior VA loans: payoff/sale evidence for restoration if needed"],"Reserve / National Guard":["NGB 22 + NGB 23 or branch points statement (6 good years) or DD-214 for Title 10 activation","COE — code 10 vs 11","Drill pay two-year history and continuance, or use only to offset ≤24-month debts","Civilian employment VOE","Honorable discharge or still serving (unit letter)"],"Surviving spouse":["VA 26-1817 COE request with marriage certificate, veteran's DD-214, death certificate/DIC award","Confirm DIC receipt — funding-fee exempt (codes 06/07)","Remarriage after 57 (on/after 12/16/2003) still eligible","Own income/credit qualify the spouse; occupancy by the spouse"],"Veteran + non-veteran (joint)":["Prior approval package to the RLC — build 2–3 weeks into the contract","25% total investment: guaranty + down payment (Joint calculator)","Veteran qualifies on own income for their share; non-veteran qualifies separately","Funding fee on the veteran's share only","Veteran occupies; non-veteran need not"],"IRRRL":["Existing VA loan number, current note, payment history (210 days + 6 payments)","NTB test: 50 bps fixed-to-fixed / 200 bps fixed-to-ARM / ARM-to-fixed","Recoupment ≤36 months on allowable costs; no fees if P&I rises without recoupment","Prior occupancy certification; no cash back; ≤2 discount points financed","0.5% funding fee unless exempt; 26-8923 worksheet"],"Assumption (ROL / SOE)":["Contact the servicer (VALERI) — assumption package and processing fee","Buyer qualifies (credit/income/residual) like a new loan; 0.5% fee unless exempt","Price above balance: cash or second lien per Circular 26-24-17","SOE if buyer is a veteran with enough entitlement and will occupy — written request by both parties","Seller: ROL letter in hand before closing; entitlement status noted on COE afterwards"]};
